import 'package:firebase_core/firebase_core.dart';

/// Hand-written Firebase options (NOT generated by `flutterfire configure`).
///
/// The real web config is passed at build time with `--dart-define`:
///   FIREBASE_API_KEY, FIREBASE_AUTH_DOMAIN, FIREBASE_PROJECT_ID,
///   FIREBASE_STORAGE_BUCKET, FIREBASE_MESSAGING_SENDER_ID, FIREBASE_APP_ID
///   (and optionally FIREBASE_MEASUREMENT_ID).
///
/// Until they are provided the app runs in "unconfigured" mode: it renders
/// the login screen and explains that setup is still pending. No real keys
/// are ever hardcoded here.
///
/// The web `apiKey` and friends are public-by-design identifiers for a
/// Firebase web app (they are shipped in the JS bundle by every Firebase
/// web app). Security does NOT come from hiding them — it comes from
/// Firestore rules + Firebase Auth + App Check (see FIREBASE.md and
/// firestore.rules). Never put a service-account key or Admin SDK
/// credential in this file.
class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    // The same public web config is used on every platform for now.
    // Once the Android / iOS apps are registered in the Firebase console,
    // per-platform options (and android/app/google-services.json) should
    // replace this so each native app is identified properly.
    // See FIREBASE.md ("Native apps" section).
    return const FirebaseOptions(
      apiKey: _apiKey,
      authDomain: _authDomain,
      projectId: _projectId,
      storageBucket: _storageBucket,
      messagingSenderId: _messagingSenderId,
      appId: _appId,
      measurementId: _measurementId,
    );
  }

  static const _apiKey = String.fromEnvironment(
    'FIREBASE_API_KEY',
    defaultValue: 'placeholder-api-key',
  );
  static const _authDomain = String.fromEnvironment(
    'FIREBASE_AUTH_DOMAIN',
    defaultValue: 'placeholder.firebaseapp.com',
  );
  static const _projectId = String.fromEnvironment(
    'FIREBASE_PROJECT_ID',
    defaultValue: 'placeholder-project',
  );
  static const _storageBucket = String.fromEnvironment(
    'FIREBASE_STORAGE_BUCKET',
    defaultValue: 'placeholder.appspot.com',
  );
  static const _messagingSenderId = String.fromEnvironment(
    'FIREBASE_MESSAGING_SENDER_ID',
    defaultValue: '000000000000',
  );
  static const _appId = String.fromEnvironment(
    'FIREBASE_APP_ID',
    defaultValue: '1:000000000000:web:placeholder',
  );
  static const _measurementId = String.fromEnvironment(
    'FIREBASE_MEASUREMENT_ID',
    defaultValue: '',
  );

  /// True once a real Firebase project has been wired in.
  static bool get isConfigured =>
      !_projectId.contains('placeholder') &&
      !_apiKey.contains('placeholder');
}
